@Override
    public void setConfiguration(Map<String, String> configuration) throws RuntimeException {
        if (configuration.containsKey(CFG_CLASSES)) {
            classes = Arrays.asList(Pattern.compile("\\s+").split(configuration.get(CFG_CLASSES)));
        }
    }
